"""Guide H3 with the original loaded/empty cart and human contact paintings."""
import json
import numpy as np
from PIL import Image
import produce as p
UID='unit_neutral_cartbow_tenders'
LEGACY=p.ROOT/'art/animation/source/poses'/UID
FRAMES=json.loads((LEGACY/'packing.json').read_bytes())['frames']
IDENTITY=('One original Cartbow Tender, one adult human man with exactly TWO arms and TWO legs. Brown leather cap with goggles, red scarf and headband tails, mustard yellow coat, rolled cream sleeves, dark brown leather apron, brown gloves, strapped brown trousers and boots, belt tools and side bolt case. He stands behind his ONE original two-wheel wooden crossbow cart, facing screen right. Exactly TWO wooden spoked wheels with iron rims, same wooden chassis, metal rail, bronze rear crank, original curved wooden bow limbs and ONE continuous string. Original red/white fletched reserve bolts remain in the side rack. Near arm is screen-left arm on rear crank/handle; far arm crosses to screen-right rail/handle. Both are ordinary human hands, never extra arms or fingers. Original body proportions, face, clothing, loaded bolt and cart geometry remain coherent. ')
PLATE=(' Locked original elevated three-quarter orthographic camera; full man, both boots, both cart wheels and entire bow inside960x544 with generous margins, fixed body scale and centered root. Uniform saturated GREEN RGB0,255,0 background in EVERY frame, no floor, gradient, ground shadow, text, other characters, smoke, flashes, beams or magic. Genuine human joints, hands and cart mechanism; no whole-sprite warping. ')

def ref(index):
 f=dict(FRAMES[index]);f['source']=(LEGACY/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 if f['source'].endswith('alpha/poses.png'):f['scale']*=.90
 elif 'continuity-alpha/' in f['source']:f['scale']*=.85
 return f

def config(clip,indices,guides,last,description,seed):
 c=dict(unit_id=UID,clip=clip,canvas=[960,544],anchor=[470,480],scale=.5,key_rgb=[0,255,0],seed=seed,references=[ref(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+description+PLATE).strip(),protected_foreground_chroma=0,tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True);assert not (out/'submission.json').exists();p.write(out/'config.json',c);p.prepare(out,c)
 maxima=[]
 for i in range(len(indices)):
  a=np.asarray(Image.open(out/f'guide_{i}_rgba.png')).astype(int);mask=a[:,:,3]>=245;maxima.append(int((a[:,:,1]-np.maximum(a[:,:,0],a[:,:,2]))[mask].max()))
 c['protected_foreground_chroma']=max(maxima)+2;p.write(out/'config.json',c);p.verify(out,c)
 p.write(out/'foreground_measurement.json',dict(opaque_alpha_minimum=245,original_guide_green_minus_max_red_blue=maxima,margin=2,protected_foreground_chroma=c['protected_foreground_chroma']))

def main():
 config('move',[17,2,3],[[24,1],[50,2],[90,1]],0,'One full reciprocal HUMAN walking cycle IN PLACE while pushing the loaded cart. Alternate BOTH legs: first rear screen-left boot lifts, passes under pelvis and plants in front; then other screen-right boot lifts, passes and plants. Knees bend and ankles flex, supported planted foot each step. Both original hands stay on cart handles, elbows extend/flex as weight shifts. TWO wheels rotate naturally FORWARD on fixed axle as though rolling, axle centers stay centered, bow and chassis rigid. Match original contact at end; no hopping, marching on one foot, reversed wheel or root travel. Keep bolt loaded; no firing.',2026101001)
 config('attack',[17,4,5,6],[[26,1],[56,2],[88,3]],0,'One physical melee SHOVE using the whole original loaded cart, not shooting. Lean back and bend elbows into anticipation26; step and straighten arms to shove rigid chassis toward screen right56, knees transferring weight and wheels rolling with small local forward motion. Recover arms and legs88 and roll back to exact original ready. The original loaded bolt stays on rail throughout; string stays drawn, no firing, flying bolt, invented sword or punch. Both hands continuously grip original cart.',2026101002)
 config('hit',[17,8],[[34,1]],0,'One brief HUMAN hit recoil without an incoming object or projectile. Torso rocks back, knees bend, elbows flex with both hands on original cart; wheels and chassis remain intact. Recover body and knees to ready. No fall, firing, dropped bolt, extra arm, impacts, explosion or attached new equipment.',2026101003)
 config('defend',[17,7],[[44,1]],1,'One dedicated defensive human crouch behind the loaded crossbow cart. Flex both knees and lower torso behind bow/rail, bend both elbows without losing two grips; cap and face remain visible. HOLD final low planted guard. Cart remains upright, exactly two wheels, bolt loaded and string drawn. No new shield, firing, prone fall or return to standing.',2026101004)
 config('cast',[17],[],0,'One physical support/rally signal, not magic. Boots and cart stay planted. Keep near screen-left gloved hand on original rear crank/handle. Lift ONLY far screen-right hand away from rail, bend elbow and raise EMPTY palm to shoulder height toward screen right in a clear ready signal; all five fingers coherent, no object appears. Briefly hold the raised palm, then lower arm and regrip the SAME original far handle, returning to exact ready. One moving arm plus one steady arm, no new arm, missing hand, spell, firing or whole-body wobble.',2026101005)
 config('death',[17,13,14,15,16],[[26,1],[44,2],[74,3]],4,'One continuous HUMAN collapse beside the intact cart. Both knees buckle26, man sinks to kneel44 while hands slide from original handles. He loses support and falls onto his side toward screen left74, both arms and legs fold naturally. End supplied prone body with head screen left, boots screen right and BOTH arms resting on ground, same cap/scarf/clothing intact. The loaded wooden cart stays upright and grounded on two wheels, no breakage or morphing into a second cart. No stand-up recovery, disappearance, extra limbs, firing or shrinking corpse.',2026101006)
 config('ranged',[17,10,11,12,9],[[24,1],[48,2],[66,3],[94,4]],0,'One crossbow SHOT then reload. Human leans into supplied loaded aim24, steadying rail with far hand and near hand at rear trigger/crank. Release at48: original string snaps from drawn rear position to FRONT bow line and single loaded bolt leaves along rail toward screen right; no second arrow, beams, flash or smoke. Immediately EMPTY rail, shot recoil then follow-through66. Near hand turns original rear crank94 while far hand places ONE reserve bolt from side rack onto rail; string retracts naturally and returns to exact original loaded ready. Cart stays planted on exactly two wheels, two human arms and legs remain coherent. One shot only. Detached bolt flight belongs to runtime; prefer no visible projectile beyond the rail tip.',2026101007)
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,ground_anchor=[470,480],fixed_source_family_multipliers={'alpha/poses.png':.90,'continuity-alpha':.85,'idle-v2/hands-alpha.png':1},reason='Original standing212px and separate continuity223px versus accepted192px articulated idle; one anatomical factor per original family, crouches/corpse not normalized, idle unchanged.'))
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[n+'_h3_v1' for n in ['move','attack','hit','defend','cast','death','ranged']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='Solo Cartbow Tenders seven H3 actions; two arms/two legs and exactly two cart wheels. Review original motion, reciprocal support, grips and draw/release/reload before publication. Retained original articulated eight-pose idle and map.')))

if __name__=='__main__':main()
